class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late final Future<DashboardData> _dataFuture;

  @override
  void initState() {
    super.initState();
    _dataFuture = _loadData();
  }

  Future<DashboardData> _loadData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    final List<dynamic> result = await Future.wait(<Future<dynamic>>[
      currencyRepository.fetchRates(const CurrencyPageRequest(pageSize: 8)),
      newsRepository.loadNewsFeed(const NewsFeedFilter(limit: 10, forceRefresh: true)),
    ]);

    return DashboardData(
      currencies: result[0] as List<CurrencyModel>,
      news: result[1] as List<NewsModel>,
    );
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<DashboardData>(
        future: _dataFuture,
        builder: (BuildContext context, AsyncSnapshot<DashboardData> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final DashboardData data = snapshot.requireData;

          return CustomScrollView(
            slivers: <Widget>[
              // Currency section
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
                  child: Text(loc.dashboardCurrencies, style: fonts.semiBold14),
                ),
              ),
              if (data.currencies.isEmpty)
                const SliverToBoxAdapter(child: SizedBox.shrink())
              else
                SliverPadding(
                  padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 8),
                  sliver: SliverList(
                    delegate: SliverChildBuilderDelegate(
                      (BuildContext context, int index) {
                        if (index == 0) return const SizedBox.shrink();
                        final CurrencyModel currency = data.currencies[index - 1];
                        return Padding(
                          key: ValueKey(currency.id),
                          padding: const EdgeInsets.only(top: 8),
                          child: CurrencyCard(model: currency),
                        );
                      },
                      childCount: data.currencies.length + 1,
                    ),
                  ),
                ),
              // News section
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
                  child: Text(loc.dashboardNews, style: fonts.semiBold14),
                ),
              ),
              if (data.news.isEmpty)
                const SliverToBoxAdapter(child: SizedBox.shrink())
              else
                SliverPadding(
                  padding: const EdgeInsets.symmetric(horizontal: 22, vertical: 8),
                  sliver: SliverList(
                    delegate: SliverChildBuilderDelegate(
                      (BuildContext context, int index) {
                        if (index == 0) return const SizedBox.shrink();
                        final NewsModel news = data.news[index - 1];
                        return Padding(
                          key: ValueKey(news.link),
                          padding: const EdgeInsets.only(top: 8),
                          child: NewsCard(model: news),
                        );
                      },
                      childCount: data.news.length + 1,
                    ),
                  ),
                ),
              const SliverToBoxAdapter(child: SizedBox(height: 40)),
            ],
          );
        },
      ),
    );
  }
}

class DashboardData {
  const DashboardData({required this.currencies, required this.news});

  final List<CurrencyModel> currencies;
  final List<NewsModel> news;
}
